using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using System.Linq;
public static class CreateSettlementScene {
 public static string Run(){if(EditorApplication.isPlaying)throw new System.Exception("Stop Play first");var source="Assets/Scenes/GameScenes/SettlementPreview.unity";var destination="Assets/Scenes/GameScenes/SettlementScene.unity";var preview="Assets/Scenes/WorldMapTools/SettlementPreview.unity";if(!string.IsNullOrEmpty(AssetDatabase.AssetPathToGUID(destination)))throw new System.Exception("Scene already exists");var guid=AssetDatabase.AssetPathToGUID(source);var scene=EditorSceneManager.OpenScene(source);EditorSceneManager.SaveScene(scene,destination,true);scene=EditorSceneManager.OpenScene(destination);var p=Object.FindFirstObjectByType<Conquest.SettlementPreview.SettlementPreview>();p.showPreviewUI=false;var walk=p.GetComponent<Conquest.SettlementPreview.SettlementWalkMode>();if(!walk||!walk.heroCameraPrefab)throw new System.Exception("Walking not configured");walk.enterOnStart=true;walk.allowPreviewExit=false;EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);EditorSceneManager.OpenScene("Assets/Scenes/GameScenes/WorldMapCampaign.unity");var bridge=Object.FindFirstObjectByType<CampaignSceneBridge>();bridge.settlementScene="SettlementScene";EditorSceneManager.MarkSceneDirty(bridge.gameObject.scene);EditorSceneManager.SaveScene(bridge.gameObject.scene);var error=AssetDatabase.MoveAsset(source,preview);if(!string.IsNullOrEmpty(error))throw new System.Exception(error);if(AssetDatabase.AssetPathToGUID(preview)!=guid)throw new System.Exception("Preview GUID changed");var build=EditorBuildSettings.scenes.Where(s=>s.path!=source&&s.path!=preview&&s.path!=destination).ToList();build.Add(new EditorBuildSettingsScene(destination,true));EditorBuildSettings.scenes=build.ToArray();AssetDatabase.SaveAssets();return "SettlementScene created; automatic walk enabled; Preview moved preserving GUID; campaign entry updated";}
}
